/**
 * Lightweight Self-Contained Offline Mermaid Graph & Diagram Renderer
 * Supports Flowchart (TD/LR/BT/RL), SequenceDiagram, Pie Chart, ClassDiagram, GitGraph
 */
(function (global) {
    let currentTheme = 'default';

    const THEMES = {
        default: {
            bg: '#ffffff',
            primaryColor: '#0969da',
            nodeBg: '#ddf4ff',
            nodeBorder: '#0969da',
            nodeText: '#24292f',
            lineColor: '#57606a',
            arrowColor: '#57606a',
            textColor: '#24292f',
            subgraphBg: '#f6f8fa',
            subgraphBorder: '#d0d7de'
        },
        dark: {
            bg: '#0d1117',
            primaryColor: '#58a6ff',
            nodeBg: '#1f242c',
            nodeBorder: '#388bfd',
            nodeText: '#c9d1d9',
            lineColor: '#8b949e',
            arrowColor: '#8b949e',
            textColor: '#c9d1d9',
            subgraphBg: '#161b22',
            subgraphBorder: '#30363d'
        }
    };

    function escapeXml(str) {
        return (str || '').replace(/[<>&'"]/g, function (c) {
            switch (c) {
                case '<': return '&lt;';
                case '>': return '&gt;';
                case '&': return '&amp;';
                case '\'': return '&apos;';
                case '"': return '&quot;';
            }
        });
    }

    function renderFlowchart(lines, theme) {
        const firstLine = lines[0].trim();
        const isHorizontal = firstLine.includes('LR') || firstLine.includes('RL');
        const nodes = new Map();
        const edges = [];

        function getOrCreateNode(id, label, shape) {
            id = id.trim();
            if (!nodes.has(id)) {
                nodes.set(id, {
                    id: id,
                    label: label ? label.trim() : id,
                    shape: shape || 'rect'
                });
            } else if (label) {
                const n = nodes.get(id);
                n.label = label.trim();
                if (shape) n.shape = shape;
            }
            return nodes.get(id);
        }

        const nodeRegex = /([a-zA-Z0-9_-]+)(?:\[\/?([^\/\]]+)\/?\]|\(([^\)]+)\)|\{([^\}]+)\}|\[\[([^\]]+)\]\]|\[\(([^\)]+)\)\])?/;

        for (let i = 1; i < lines.length; i++) {
            let line = lines[i].trim();
            if (!line || line.startsWith('%%')) continue;

            // Check for links like A -->|text| B or A --- B or A -.-> B or A ==> B
            const linkMatch = line.match(/(.*?)(-->|---|--\s*.*?\s*-->|-\.->|==>|--)(?:\|([^\|]+)\|)?\s*(.*)/);
            if (linkMatch) {
                const leftStr = linkMatch[1].trim();
                const linkType = linkMatch[2].trim();
                const linkText = linkMatch[3] ? linkMatch[3].trim() : '';
                const rightStr = linkMatch[4].trim();

                const leftNodeMatch = leftStr.match(nodeRegex);
                const rightNodeMatch = rightStr.match(nodeRegex);

                if (leftNodeMatch && rightNodeMatch) {
                    const leftId = leftNodeMatch[1];
                    const leftLabel = leftNodeMatch[2] || leftNodeMatch[3] || leftNodeMatch[4] || leftNodeMatch[5] || leftNodeMatch[6];
                    const leftShape = leftNodeMatch[3] ? 'round' : (leftNodeMatch[4] ? 'rhombus' : 'rect');
                    getOrCreateNode(leftId, leftLabel, leftShape);

                    const rightId = rightNodeMatch[1];
                    const rightLabel = rightNodeMatch[2] || rightNodeMatch[3] || rightNodeMatch[4] || rightNodeMatch[5] || rightNodeMatch[6];
                    const rightShape = rightNodeMatch[3] ? 'round' : (rightNodeMatch[4] ? 'rhombus' : 'rect');
                    getOrCreateNode(rightId, rightLabel, rightShape);

                    edges.push({
                        from: leftId,
                        to: rightId,
                        text: linkText,
                        type: linkType
                    });
                }
            } else {
                const singleMatch = line.match(nodeRegex);
                if (singleMatch && singleMatch[1]) {
                    const id = singleMatch[1];
                    const label = singleMatch[2] || singleMatch[3] || singleMatch[4] || singleMatch[5] || singleMatch[6];
                    const shape = singleMatch[3] ? 'round' : (singleMatch[4] ? 'rhombus' : 'rect');
                    getOrCreateNode(id, label, shape);
                }
            }
        }

        // Layout nodes
        const nodeList = Array.from(nodes.values());
        const nodeWidth = 140;
        const nodeHeight = 44;
        const gapX = isHorizontal ? 100 : 40;
        const gapY = isHorizontal ? 40 : 70;

        let totalWidth = 0;
        let totalHeight = 0;

        if (isHorizontal) {
            nodeList.forEach((node, idx) => {
                node.x = 40 + idx * (nodeWidth + gapX);
                node.y = 40 + (idx % 2 === 0 ? 0 : 30);
            });
            totalWidth = 80 + nodeList.length * (nodeWidth + gapX);
            totalHeight = 160;
        } else {
            nodeList.forEach((node, idx) => {
                node.x = 40 + (idx % 2 === 0 ? 0 : 50);
                node.y = 40 + idx * (nodeHeight + gapY);
            });
            totalWidth = 260;
            totalHeight = 80 + nodeList.length * (nodeHeight + gapY);
        }

        let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${Math.max(totalWidth, 200)} ${Math.max(totalHeight, 100)}" style="background-color: transparent; max-width: 100%; height: auto; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">`;
        
        // Defs for marker arrows
        svg += `<defs>
            <marker id="arrow-${theme}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="${THEMES[theme].arrowColor}"/>
            </marker>
        </defs>`;

        // Draw Edges
        edges.forEach(edge => {
            const fromNode = nodes.get(edge.from);
            const toNode = nodes.get(edge.to);
            if (fromNode && toNode) {
                const x1 = fromNode.x + nodeWidth / 2;
                const y1 = fromNode.y + nodeHeight;
                const x2 = toNode.x + nodeWidth / 2;
                const y2 = toNode.y;

                if (isHorizontal) {
                    const hx1 = fromNode.x + nodeWidth;
                    const hy1 = fromNode.y + nodeHeight / 2;
                    const hx2 = toNode.x;
                    const hy2 = toNode.y + nodeHeight / 2;
                    svg += `<path d="M ${hx1} ${hy1} C ${hx1 + 40} ${hy1}, ${hx2 - 40} ${hy2}, ${hx2} ${hy2}" fill="none" stroke="${THEMES[theme].lineColor}" stroke-width="2" marker-end="url(#arrow-${theme})"/>`;
                    if (edge.text) {
                        const midX = (hx1 + hx2) / 2;
                        const midY = (hy1 + hy2) / 2 - 8;
                        svg += `<text x="${midX}" y="${midY}" fill="${THEMES[theme].textColor}" font-size="12" text-anchor="middle">${escapeXml(edge.text)}</text>`;
                    }
                } else {
                    svg += `<path d="M ${x1} ${y1} C ${x1} ${y1 + 30}, ${x2} ${y2 - 30}, ${x2} ${y2}" fill="none" stroke="${THEMES[theme].lineColor}" stroke-width="2" marker-end="url(#arrow-${theme})"/>`;
                    if (edge.text) {
                        const midX = (x1 + x2) / 2 + 10;
                        const midY = (y1 + y2) / 2;
                        svg += `<text x="${midX}" y="${midY}" fill="${THEMES[theme].textColor}" font-size="12" text-anchor="start">${escapeXml(edge.text)}</text>`;
                    }
                }
            }
        });

        // Draw Nodes
        nodeList.forEach(node => {
            const rx = node.shape === 'round' ? 16 : (node.shape === 'rhombus' ? 4 : 6);
            svg += `<g class="node">
                <rect x="${node.x}" y="${node.y}" width="${nodeWidth}" height="${nodeHeight}" rx="${rx}" fill="${THEMES[theme].nodeBg}" stroke="${THEMES[theme].nodeBorder}" stroke-width="1.5"/>
                <text x="${node.x + nodeWidth / 2}" y="${node.y + nodeHeight / 2 + 5}" fill="${THEMES[theme].nodeText}" font-size="13" font-weight="500" text-anchor="middle">${escapeXml(node.label)}</text>
            </g>`;
        });

        svg += `</svg>`;
        return svg;
    }

    function renderSequence(lines, theme) {
        const actors = [];
        const messages = [];

        lines.forEach(line => {
            line = line.trim();
            if (!line || line.startsWith('%%') || line.startsWith('sequenceDiagram')) return;

            const actorMatch = line.match(/^actor\s+(.+)|^participant\s+(.+)/);
            if (actorMatch) {
                const name = (actorMatch[1] || actorMatch[2]).trim();
                if (!actors.includes(name)) actors.push(name);
                return;
            }

            const msgMatch = line.match(/^([^-]+)(->>|-->>|->|-->)([^:]+):(.*)/);
            if (msgMatch) {
                const from = msgMatch[1].trim();
                const type = msgMatch[2].trim();
                const to = msgMatch[3].trim();
                const text = msgMatch[4].trim();
                if (!actors.includes(from)) actors.push(from);
                if (!actors.includes(to)) actors.push(to);
                messages.push({ from, to, text, type });
            }
        });

        const actorWidth = 110;
        const actorHeight = 36;
        const gapX = 80;
        const stepY = 50;
        const totalWidth = 60 + actors.length * (actorWidth + gapX);
        const totalHeight = 120 + messages.length * stepY;

        let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${Math.max(totalWidth, 250)} ${Math.max(totalHeight, 150)}" style="background-color: transparent; max-width: 100%; height: auto; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">`;
        svg += `<defs>
            <marker id="seq-arrow-${theme}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="${THEMES[theme].arrowColor}"/>
            </marker>
        </defs>`;

        const actorPositions = {};
        actors.forEach((act, idx) => {
            const x = 40 + idx * (actorWidth + gapX);
            actorPositions[act] = x + actorWidth / 2;

            // Actor Box Top
            svg += `<rect x="${x}" y="20" width="${actorWidth}" height="${actorHeight}" rx="4" fill="${THEMES[theme].nodeBg}" stroke="${THEMES[theme].nodeBorder}" stroke-width="1.5"/>`;
            svg += `<text x="${x + actorWidth / 2}" y="43" fill="${THEMES[theme].nodeText}" font-size="13" font-weight="600" text-anchor="middle">${escapeXml(act)}</text>`;

            // Lifeline
            const bottomY = totalHeight - 40;
            svg += `<line x1="${x + actorWidth / 2}" y1="${20 + actorHeight}" x2="${x + actorWidth / 2}" y2="${bottomY}" stroke="${THEMES[theme].subgraphBorder}" stroke-width="1.5" stroke-dasharray="4 4"/>`;

            // Actor Box Bottom
            svg += `<rect x="${x}" y="${bottomY}" width="${actorWidth}" height="${actorHeight}" rx="4" fill="${THEMES[theme].nodeBg}" stroke="${THEMES[theme].nodeBorder}" stroke-width="1.5"/>`;
            svg += `<text x="${x + actorWidth / 2}" y="${bottomY + 23}" fill="${THEMES[theme].nodeText}" font-size="13" font-weight="600" text-anchor="middle">${escapeXml(act)}</text>`;
        });

        messages.forEach((msg, idx) => {
            const y = 80 + idx * stepY;
            const x1 = actorPositions[msg.from] || 40;
            const x2 = actorPositions[msg.to] || 150;
            const strokeDash = msg.type.includes('--') ? 'stroke-dasharray="4 4"' : '';

            svg += `<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="${THEMES[theme].lineColor}" stroke-width="2" ${strokeDash} marker-end="url(#seq-arrow-${theme})"/>`;
            const midX = (x1 + x2) / 2;
            svg += `<text x="${midX}" y="${y - 8}" fill="${THEMES[theme].textColor}" font-size="12" text-anchor="middle">${escapeXml(msg.text)}</text>`;
        });

        svg += `</svg>`;
        return svg;
    }

    function renderPie(lines, theme) {
        let title = 'Pie Chart';
        const slices = [];
        const colors = ['#0969da', '#2da44e', '#bf8700', '#cf222e', '#8250df', '#1f6feb', '#238636'];

        lines.forEach(line => {
            line = line.trim();
            if (!line || line.startsWith('%%')) return;
            if (line.startsWith('pie')) {
                const titleMatch = line.match(/title\s+(.*)/);
                if (titleMatch) title = titleMatch[1].trim();
                return;
            }
            const sliceMatch = line.match(/^"([^"]+)"\s*:\s*([0-9.]+)/);
            if (sliceMatch) {
                slices.push({
                    label: sliceMatch[1].trim(),
                    value: parseFloat(sliceMatch[2])
                });
            }
        });

        const total = slices.reduce((acc, s) => acc + s.value, 0) || 1;
        let cumulativeAngle = 0;
        const cx = 140, cy = 130, r = 90;

        let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 260" style="background-color: transparent; max-width: 100%; height: auto; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">`;
        svg += `<text x="210" y="25" fill="${THEMES[theme].textColor}" font-size="16" font-weight="600" text-anchor="middle">${escapeXml(title)}</text>`;

        slices.forEach((slice, idx) => {
            const angle = (slice.value / total) * 2 * Math.PI;
            const x1 = cx + r * Math.cos(cumulativeAngle);
            const y1 = cy + r * Math.sin(cumulativeAngle);
            const x2 = cx + r * Math.cos(cumulativeAngle + angle);
            const y2 = cy + r * Math.sin(cumulativeAngle + angle);
            const largeArc = angle > Math.PI ? 1 : 0;
            const color = colors[idx % colors.length];

            const pathData = `M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2} Z`;
            svg += `<path d="${pathData}" fill="${color}" stroke="${THEMES[theme].bg}" stroke-width="1.5"/>`;

            // Legend
            const legY = 60 + idx * 24;
            const percent = ((slice.value / total) * 100).toFixed(1) + '%';
            svg += `<rect x="270" y="${legY}" width="14" height="14" rx="2" fill="${color}"/>`;
            svg += `<text x="292" y="${legY + 12}" fill="${THEMES[theme].textColor}" font-size="12">${escapeXml(slice.label)} (${percent})</text>`;

            cumulativeAngle += angle;
        });

        svg += `</svg>`;
        return svg;
    }

    function render(source, isDarkMode) {
        const theme = isDarkMode ? 'dark' : 'default';
        const lines = (source || '').trim().split('\n').map(l => l.trim()).filter(l => l.length > 0);
        if (lines.length === 0) return '';

        const firstLine = lines[0].toLowerCase();
        try {
            if (firstLine.startsWith('flowchart') || firstLine.startsWith('graph')) {
                return renderFlowchart(lines, theme);
            } else if (firstLine.startsWith('sequencediagram')) {
                return renderSequence(lines, theme);
            } else if (firstLine.startsWith('pie')) {
                return renderPie(lines, theme);
            } else {
                return renderFlowchart(lines, theme);
            }
        } catch (err) {
            console.error('Mermaid render error:', err);
            return '<pre class="language-mermaid"><code>' + escapeXml(source) + '</code></pre>';
        }
    }

    global.mermaid = {
        initialize: function (opts) {
            if (opts && opts.theme) {
                currentTheme = opts.theme === 'dark' ? 'dark' : 'default';
            }
        },
        render: render,
        run: function (options) {
            const isDark = currentTheme === 'dark';
            const elements = document.querySelectorAll('pre.mermaid, div.mermaid, .language-mermaid');
            elements.forEach(function (el) {
                const src = el.textContent || el.innerText;
                const svg = render(src, isDark);
                const container = document.createElement('div');
                container.className = 'mermaid-rendered';
                container.innerHTML = svg;
                if (el.parentNode) {
                    el.parentNode.replaceChild(container, el);
                }
            });
        }
    };
})(window);
